/// Read back [`to_wire`](Self::to_wire).
pub fn parse(line: &str) -> Option<Self> {
    let mut parts = line.split(' ');
    let subject = Subject::from_hex(parts.next()?)?;
    let last_fired_ms = parts.next()?.parse().ok()?;
    let period = Period::parse(parts.next()?)?;
    Some(Self {
        subject,
